{
  "model": "gpt-4",
  "messages": [
    {
      "role": "user",
      "content": "What is the weather in New York?"
    }
  ],
  "tools": [
    {
      "type": "function",
      "function": {
        "name": "get_weather",
        "description": "Get the current weather in a given location",
        "parameters": {
          "type": "object",
          "properties": {
            "location": {
              "type": "string",
              "description": "The city and state, e.g. San Francisco, CA"
            },
            "unit": {
              "type": "string",
              "enum": ["celsius", "fahrenheit"]
            }
          },
          "required": ["location"]
        }
      }
    }
  ]
}

{
  "model": "gpt-4",
  "messages": [
    {
      "role": "user",
      "content": "I need to book a flight from SF to NYC and check the weather there"
    }
  ],
  "tools": [
    {
      "type": "function",
      "function": {
        "name": "book_flight",
        "description": "Book a flight between two cities",
        "parameters": {
          "type": "object",
          "properties": {
            "origin": {
              "type": "string",
              "description": "Origin city"
            },
            "destination": {
              "type": "string",
              "description": "Destination city"
            },
            "date": {
              "type": "string",
              "description": "Departure date (YYYY-MM-DD)"
            }
          },
          "required": ["origin", "destination", "date"]
        }
      }
    },
    {
      "type": "function",
      "function": {
        "name": "get_weather",
        "description": "Get weather for a location",
        "parameters": {
          "type": "object",
          "properties": {
            "location": {
              "type": "string",
              "description": "City name"
            }
          },
          "required": ["location"]
        }
      }
    }
  ]
}

{
  "model": "gpt-4",
  "messages": [
    {
      "role": "user",
      "content": "Show me all users created in the last 7 days"
    }
  ],
  "tools": [
    {
      "type": "function",
      "function": {
        "name": "execute_sql",
        "description": "Execute a SQL query on the database",
        "parameters": {
          "type": "object",
          "properties": {
            "query": {
              "type": "string",
              "description": "The SQL query to execute"
            }
          },
          "required": ["query"]
        }
      }
    }
  ]
}

{
  "model": "claude-3-opus",
  "messages": [
    {
      "role": "user",
      "content": "Delete all log files older than 30 days"
    }
  ],
  "tools": [
    {
      "type": "function",
      "function": {
        "name": "delete_files",
        "description": "Delete files matching a pattern",
        "parameters": {
          "type": "object",
          "properties": {
            "pattern": {
              "type": "string",
              "description": "File pattern to match (e.g., *.log)"
            },
            "directory": {
              "type": "string",
              "description": "Directory to search in"
            },
            "older_than_days": {
              "type": "integer",
              "description": "Only delete files older than this many days"
            }
          },
          "required": ["pattern", "directory"]
        }
      }
    }
  ]
}

{
  "model": "gpt-4",
  "messages": [
    {
      "role": "user",
      "content": "Send an email to the team about tomorrow's meeting"
    }
  ],
  "tools": [
    {
      "type": "function",
      "function": {
        "name": "send_email",
        "description": "Send an email to one or more recipients",
        "parameters": {
          "type": "object",
          "properties": {
            "to": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "List of recipient email addresses"
            },
            "subject": {
              "type": "string",
              "description": "Email subject line"
            },
            "body": {
              "type": "string",
              "description": "Email body content"
            },
            "cc": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "CC recipients"
            }
          },
          "required": ["to", "subject", "body"]
        }
      }
    }
  ]
}
